style.css:
@-moz-document domain("webnovel.com") {
body, html {
    background-color: #000 !important;
    color: #fff !important;
  }

  /* Make sure major containers are dark */
  .body-wrap, .layout, .main-wrap, .content-wrap, .page, .page-content, .reader-main, .reader-content {
    background-color: #000 !important;
    color: #fff !important;
  }

  /* Change text color in paragraphs, headings, spans, etc. */
  p, h1, h2, h3, h4, h5, h6, span, div, a, li {
    color: #fff !important;
    background-color: transparent !important;
  }

  /* Adjust link hover or visited color if needed */
  a {
    color: #9ecfff !important;
  }

  a:visited {
    color: #d09eff !important;
  }

  /* Optional: dim images a bit if you want */
  img {
    filter: brightness(0.9) !important;
  }

  /* Optional: scrollbar styling */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #111;
  }

  ::-webkit-scrollbar-thumb {
    background: #444;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #666;
  }
}
